//! The Emit V2 pool contract for alloy.
//!
//! [`EmitV2Pool`] is generated by alloy's `sol!` from `abi/EmitV2Pool.json`: the forge artifact
//! of `contracts/src/EmitV2Pool.sol` (its ABI and bytecode), checked in so a build needs no
//! Solidity toolchain. It has every call and event, and `EmitV2Pool::deploy` from the bytecode.
//! CI rebuilds the contracts and fails if the artifact drifts (`mise run abi:check`).
//!
//! [`escrow_log`] turns the pool's `Escrowed` / `EscrowClosed` logs into emit-protocol's
//! [`EscrowLog`], and [`ESCROW_TOPICS`] filters for them.

use alloy::primitives::B256;
use alloy::rpc::types::Log;
use alloy::sol_types::SolEvent;
use emit_protocol::{ChainCommitment, EnvCommit, EscrowEventKind, EscrowLog, NoteCommitment};

alloy::sol!(
    #[allow(missing_docs, clippy::too_many_arguments)]
    #[sol(rpc)]
    #[derive(Debug)]
    EmitV2Pool,
    "abi/EmitV2Pool.json"
);

/// The topics of the pool's two escrow events, for one log filter over both: opens and closes of
/// a range then arrive in one answer, in chain order.
pub const ESCROW_TOPICS: [B256; 2] = [
    EmitV2Pool::Escrowed::SIGNATURE_HASH,
    EmitV2Pool::EscrowClosed::SIGNATURE_HASH,
];

#[derive(Debug, thiserror::Error)]
#[error("undecodable escrow log: {0}")]
pub struct DecodeError(#[from] alloy::sol_types::Error);

/// The escrow event in `log`, if it is one (`None` for the pool's other events). An escrow log
/// that doesn't decode is a version mismatch between the reader and the deployment.
pub fn escrow_log(log: &Log) -> Result<Option<EscrowLog>, DecodeError> {
    Ok(match log.topic0() {
        Some(topic) if *topic == EmitV2Pool::Escrowed::SIGNATURE_HASH => {
            let e = EmitV2Pool::Escrowed::decode_log(&log.inner)?;
            Some(EscrowLog {
                seq: e.seq,
                kind: EscrowEventKind::Opened {
                    note_commitment: NoteCommitment(e.noteCommitment.0),
                    chain_commitment: ChainCommitment(e.chainCommitment.0),
                    env_commit: EnvCommit(e.envCommit.0),
                    deadline: e.deadline,
                },
            })
        }
        Some(topic) if *topic == EmitV2Pool::EscrowClosed::SIGNATURE_HASH => {
            let e = EmitV2Pool::EscrowClosed::decode_log(&log.inner)?;
            Some(EscrowLog {
                seq: e.seq,
                kind: EscrowEventKind::Closed {
                    note_commitment: NoteCommitment(e.noteCommitment.0),
                },
            })
        }
        _ => None,
    })
}

#[cfg(test)]
#[allow(clippy::unwrap_used)]
mod tests {
    use super::*;
    use alloy::primitives::{Address, Log as PrimitiveLog};

    fn log(data: PrimitiveLog) -> Log {
        Log {
            inner: data,
            ..Default::default()
        }
    }

    #[test]
    fn escrow_events_decode_into_the_protocol_types() {
        let opened = EmitV2Pool::Escrowed {
            seq: 7,
            noteCommitment: B256::repeat_byte(1),
            chainCommitment: B256::repeat_byte(2),
            envCommit: B256::repeat_byte(3),
            deadline: 99,
        };
        let pool = Address::repeat_byte(9);
        let got = escrow_log(&log(PrimitiveLog {
            address: pool,
            data: opened.encode_log_data(),
        }))
        .unwrap()
        .unwrap();
        assert_eq!(
            got,
            EscrowLog {
                seq: 7,
                kind: EscrowEventKind::Opened {
                    note_commitment: NoteCommitment([1; 32]),
                    chain_commitment: ChainCommitment([2; 32]),
                    env_commit: EnvCommit([3; 32]),
                    deadline: 99,
                },
            }
        );
        let closed = EmitV2Pool::EscrowClosed {
            seq: 8,
            noteCommitment: B256::repeat_byte(1),
        };
        let got = escrow_log(&log(PrimitiveLog {
            address: pool,
            data: closed.encode_log_data(),
        }))
        .unwrap()
        .unwrap();
        assert_eq!(got.seq, 8);
        // Another of the pool's events is not an escrow event.
        let other = EmitV2Pool::NewNullifier {
            nullifier: B256::ZERO,
        };
        assert!(
            escrow_log(&log(PrimitiveLog {
                address: pool,
                data: other.encode_log_data(),
            }))
            .unwrap()
            .is_none()
        );
    }

    /// The artifact carries the bytecode `deploy` needs.
    #[test]
    fn the_artifact_has_bytecode() {
        assert!(EmitV2Pool::BYTECODE.len() > 1000);
    }
}
